// Two categories, and the line between them is the whole design:
// SAFE FIXES are applied automatically because they cannot lose information -
// trimming, lowercasing an address, stripping www, rebuilding a missing lead_id.
// EVERYTHING ELSE is reported for a human. We never merge or delete a record.
const STALE_DAYS = Number($('config').first().json.reverify_after_days || 90);
const now = Date.now();

const slug = (s) => String(s || '')
  .toLowerCase()
  .split('')
  .map((c) => ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ? c : '-'))
  .join('')
  .split('-')
  .filter(Boolean)
  .join('-');

const inputItems = $input.all();
const rows = inputItems.map((i) => i.json);
const issues = {
  duplicate_email: [],
  duplicate_lead_id: [],
  missing_domain: [],
  malformed_email: [],
  likely_job_change: [],
  no_owner_in_crm: [],
  never_synced: []
};
const reviewItems = [];
const fixes = { trimmed: 0, lowercased: 0, domain_normalised: 0, lead_id_rebuilt: 0 };

const byEmail = {};
const byLeadId = {};
const out = [];
const stale = [];

for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
  const row = rows[rowIndex];
  const cleaned = Object.assign({}, row);
  // Original Google Sheets row number (header is row 1).
  cleaned._source_row_number = rowIndex + 2;
  let changed = false;

  // --- safe fixes ---
  for (const key of ['first_name', 'last_name', 'company', 'title', 'email', 'domain']) {
    if (typeof cleaned[key] === 'string' && cleaned[key] !== cleaned[key].trim()) {
      cleaned[key] = cleaned[key].trim();
      fixes.trimmed++;
      changed = true;
    }
  }

  if (cleaned.email && cleaned.email !== String(cleaned.email).toLowerCase()) {
    cleaned.email = String(cleaned.email).toLowerCase();
    fixes.lowercased++;
    changed = true;
  }

  if (cleaned.domain) {
    let d = String(cleaned.domain).toLowerCase();
    d = d.split('//').pop().split('/')[0];
    if (d.startsWith('www.')) d = d.slice(4);
    if (d !== cleaned.domain) { cleaned.domain = d; fixes.domain_normalised++; changed = true; }
  }

  if (!cleaned.lead_id && cleaned.domain) {
    cleaned.lead_id = slug(cleaned.domain) + '-' + slug((cleaned.first_name || '') + ' ' + (cleaned.last_name || ''));
    fixes.lead_id_rebuilt++;
    changed = true;
  }

  // --- reported, never auto-resolved ---
  const label = (cleaned.lead_id || cleaned.email || 'unnamed row');

  const addReview = (issue_type, details, recommended_action) => {
    reviewItems.push({
      audit_id: new Date(now).toISOString().slice(0, 10),
      audited_at: new Date(now).toISOString(),
      source_row_number: cleaned._source_row_number,
      lead_id: cleaned.lead_id || '',
      email: cleaned.email || '',
      first_name: cleaned.first_name || '',
      last_name: cleaned.last_name || '',
      company: cleaned.company || '',
      issue_type,
      details,
      recommended_action,
      status: 'Pending'
    });
  };

  if (cleaned.email && !String(cleaned.email).includes('@')) {
    issues.malformed_email.push(label);
    addReview('malformed_email', 'Email does not contain @', 'Review and correct email');
  }
  if (!cleaned.domain) {
    issues.missing_domain.push(label);
    addReview('missing_domain', 'Domain is missing', 'Research and add company domain');
  }

  if (cleaned.email) {
    if (byEmail[cleaned.email]) {
      issues.duplicate_email.push(cleaned.email);
      addReview('duplicate_email', 'Email appears more than once', 'Review duplicate records; do not merge automatically');
    }
    byEmail[cleaned.email] = true;
  }
  if (cleaned.lead_id) {
    if (byLeadId[cleaned.lead_id]) {
      issues.duplicate_lead_id.push(cleaned.lead_id);
      addReview('duplicate_lead_id', 'Lead ID appears more than once', 'Review duplicate records; do not merge automatically');
    }
    byLeadId[cleaned.lead_id] = true;
  }

  if (String(cleaned.email_status) === 'invalid' && String(cleaned.email_source || '') !== 'pattern') {
    issues.likely_job_change.push(label);
    addReview('likely_job_change', 'Email is invalid and may indicate a job change', 'Research current employment before reactivating');
  }

  const isLive = ['queued', 'sent', 'replied', 'booked'].indexOf(String(cleaned.stage || '')) !== -1;
  if (isLive && !cleaned.ghl_contact_id) {
    issues.never_synced.push(label);
    addReview('never_synced', 'Live lead has no CRM contact ID', 'Check CRM synchronization');
  }
  if (isLive && cleaned.ghl_contact_id && !cleaned.crm_owner) {
    issues.no_owner_in_crm.push(label);
    addReview('no_owner_in_crm', 'CRM contact has no owner', 'Assign a CRM owner');
  }

  // --- decay: addresses verified long enough ago to be worth rechecking ---
  const verifiedAt = Date.parse(cleaned.enriched_at || cleaned.updated_at || '') || 0;
  const ageDays = verifiedAt ? Math.floor((now - verifiedAt) / 86400000) : 999;
  if (cleaned.email && ageDays > STALE_DAYS && String(cleaned.stage || '') !== 'suppressed') {
    stale.push({ lead_id: cleaned.lead_id, email: cleaned.email, age_days: ageDays });
  }

  if (changed) { cleaned.updated_at = new Date().toISOString(); out.push({ json: cleaned }); }
}

const summary = {
  total_rows: rows.length,
  fixes: fixes,
  issues: issues,
  stale_count: stale.length,
  stale_sample: stale.slice(0, Number($('config').first().json.reverify_batch || 50)),
  review_items: reviewItems,
  rows_changed: out.length,
  audited_at: new Date().toISOString()
};

// IMPORTANT: summary is an internal item and is NEVER written to Leads.
const summaryItem = { json: { _audit_summary: summary } };

if (out.length === 0) {
  return [summaryItem];
}

return [
  summaryItem,
  ...out.map(item => ({ json: item.json }))
];

const items = $input.all();

const summaryItem = items.find(i => i.json && i.json._audit_summary);
const leadItems = items.filter(i => i.json && !i.json._audit_summary);

const summary = summaryItem
  ? summaryItem.json._audit_summary
  : {
      total_rows: 0,
      fixes: {},
      issues: {},
      stale_count: 0,
      stale_sample: [],
      review_items: [],
      rows_changed: 0,
      audited_at: new Date().toISOString()
    };

return [{
  json: {
    _audit_summary: summary,
    _has_fixes: leadItems.length > 0,
    _lead_items: leadItems.map(i => i.json),
    _review_items: summary.review_items || []
  }
}];

const summary = $('prepare audit results').first().json._audit_summary;
const sample = (summary && summary.stale_sample) || [];

if (!sample.length) {
  return [{ json: { _nothing_stale: true } }];
}

return sample.map(s => ({ json: s }));

const input = $input.all();
const out = [];

for (const item of input) {
  const j = item.json || {};

  const lead_id = j.lead_id || j.data?.lead_id;
  const email = j.email || j.data?.email;

  // NeverBounce v4 commonly exposes the classification as `result`.
  const result = String(
    j.result ||
    j.data?.result ||
    j.status ||
    ''
  ).toLowerCase();

  const now = new Date().toISOString();

  const patch = {
    lead_id,
    email_status: result,
    reverified_at: now,
    updated_at: now
  };

  if (result === 'invalid') {
    patch.stage = 'suppressed';
    patch.needs_reresearch = true;
    patch.suppression_reason = 'address stopped verifying - likely job change';
  }

  out.push({ json: patch });
}

return out;

const s = $('prepare audit results').first().json._audit_summary || {};
const reviewItems = s.review_items || [];

let rechecked = [];
try {
  rechecked = $('apply recheck results').all();
} catch (e) {
  rechecked = [];
}

const downgraded = rechecked.filter(
  r => String(r.json.email_status || '').toLowerCase() === 'invalid'
).length;

const pct = n =>
  s.total_rows ? Math.round((n / s.total_rows) * 1000) / 10 : 0;

const i = s.issues || {};
const f = s.fixes || {};

const counts = {
  duplicate_email: (i.duplicate_email || []).length,
  duplicate_lead_id: (i.duplicate_lead_id || []).length,
  malformed_email: (i.malformed_email || []).length,
  missing_domain: (i.missing_domain || []).length,
  likely_job_change: (i.likely_job_change || []).length,
  never_synced: (i.never_synced || []).length,
  no_owner_in_crm: (i.no_owner_in_crm || []).length
};

const issueCount = Object.values(counts).reduce((a, b) => a + b, 0);

const fixCount =
  Number(f.trimmed || 0) +
  Number(f.lowercased || 0) +
  Number(f.domain_normalised || 0) +
  Number(f.lead_id_rebuilt || 0);

const health = Math.max(0, 100 - Math.round(pct(issueCount)));

const lines = [
  ':broom: *Data quality - ' + String(s.audited_at || '').slice(0, 10) + '*',
  'Health *' + health + '/100* across ' + s.total_rows + ' rows.',
  '',
  '*Fixed automatically* (' + fixCount + '): ' +
    Number(f.trimmed || 0) + ' trimmed, ' +
    Number(f.lowercased || 0) + ' lowercased, ' +
    Number(f.domain_normalised || 0) + ' domains normalised, ' +
    Number(f.lead_id_rebuilt || 0) + ' ids rebuilt.',
  '',
  '*Needs a human* (' + issueCount + ', ' + pct(issueCount) + '%):'
];

const labels = [
  ['duplicate email', counts.duplicate_email],
  ['duplicate lead id', counts.duplicate_lead_id],
  ['malformed email', counts.malformed_email],
  ['missing domain', counts.missing_domain],
  ['likely job change', counts.likely_job_change],
  ['live lead never synced', counts.never_synced],
  ['CRM contact has no owner', counts.no_owner_in_crm]
];

for (const [label, count] of labels) {
  if (count) lines.push('  - ' + count + ' ' + label);
}

if (issueCount === 0) lines.push('  - nothing');

if ($('config').first().json.neverbounce_enabled) {
  lines.push(
    '',
    '*Decay:* ' + s.stale_count +
    ' addresses older than ' +
    ($('config').first().json.reverify_after_days || 90) +
    ' days; rechecked ' + rechecked.length +
    ', ' + downgraded +
    ' no longer valid and suppressed.'
  );
} else {
  lines.push(
    '',
    '*Decay:* NeverBounce is disabled; ' +
    s.stale_count +
    ' stale addresses detected but not rechecked.'
  );
}

lines.push(
  '',
  '_Individual human-review items are written to the Data Quality sheet with status Pending._'
);

return [{
  json: {
    text: lines.join('\n'),
    audited_at: s.audited_at,
    total_rows: s.total_rows,
    health_score: health,
    auto_fixed: fixCount,
    needs_human: issueCount,
    rechecked: rechecked.length,
    downgraded,
    review_items: reviewItems
  }
}];

// CRM DATA HYGIENE - CONFIG
// Edit values only in this node.
//
// DRY_RUN true              -> the audit reports, nothing is written back.
// NEVERBOUNCE_API_KEY blank  -> NeverBounce branch is skipped.
// ALERT_WEBHOOK_URL blank    -> webhook branch is skipped.

// Ships true. The audit runs and reports, and nothing is written back.
// Set to false only after you have read a full dry-run report.
const DRY_RUN = true;

const LEADS_SHEET_ID = 'YOUR_GOOGLE_SHEET_ID';

const REVERIFY_AFTER_DAYS = 90;
const REVERIFY_BATCH = 50;

// Optional: leave blank to skip NeverBounce completely.
const NEVERBOUNCE_API_KEY = '';

// Optional: leave blank to skip webhook notification completely.
const ALERT_WEBHOOK_URL = '';

return [{
  json: {
    dry_run: DRY_RUN,
    write_enabled: DRY_RUN !== true,
    leads_sheet_id: LEADS_SHEET_ID,
    reverify_after_days: REVERIFY_AFTER_DAYS,
    reverify_batch: REVERIFY_BATCH,
    neverbounce_api_key: NEVERBOUNCE_API_KEY,
    alert_webhook_url: ALERT_WEBHOOK_URL,
    neverbounce_enabled: NEVERBOUNCE_API_KEY.trim() !== '',
    webhook_enabled: ALERT_WEBHOOK_URL.trim() !== ''
  }
}];

const rows = $('prepare audit results').first().json._lead_items || [];

if (!rows.length) {
  return [{ json: { _nothing_to_write: true } }];
}

return rows.map(row => ({ json: row }));

const items = $('build quality report').first().json.review_items || [];
if (!items.length) return [{ json: { _no_review_items: true } }];
return items.map(item => ({ json: item }));
